script:
attendance_time = frappe.utils.get_datetime(doc.time)
attendance_date = str(attendance_time.date())

# ==================================================
# GET ACTIVE SHIFTS
# ==================================================

shift_assignments = frappe.get_all(
    "Shift Assignment",
    filters={
        "employee": doc.employee,
        "docstatus": 1
    },
    fields=[
        "shift_type",
        "start_date",
        "end_date"
    ]
)

shift_types = []

for row in shift_assignments:

    if (
        str(row.start_date) <= attendance_date
        and
        (
            not row.end_date
            or str(row.end_date) >= attendance_date
        )
    ):
        shift_types.append(row.shift_type)

# ==================================================
# DEFAULT SHIFT FALLBACK
# ==================================================

if len(shift_types) == 0:

    default_shift = frappe.db.get_value(
        "Employee",
        doc.employee,
        "default_shift"
    )

    if default_shift:
        shift_types.append(default_shift)

# ==================================================
# BUILD RESET POINTS
# ==================================================

reset_points = []

# Midnight reset

reset_points.append(
    frappe.utils.get_datetime(
        attendance_date + " 00:00:00"
    )
)

# Shift window starts

for shift_type in shift_types:

    shift_doc = frappe.get_doc(
        "Shift Type",
        shift_type
    )

    shift_start = frappe.utils.get_datetime(
        attendance_date
        + " "
        + str(shift_doc.start_time)
    )

    before_minutes = (
        shift_doc.begin_check_in_before_shift_start_time
        or 0
    )

    reset_point = frappe.utils.add_to_date(
        shift_start,
        minutes=-before_minutes,
        as_datetime=True
    )

    reset_points.append(reset_point)

# ==================================================
# FIND CURRENT CYCLE START
# ==================================================

cycle_start = reset_points[0]

for rp in reset_points:

    if rp <= attendance_time:

        if rp > cycle_start:
            cycle_start = rp

# ==================================================
# GET CHECKIN RECORDS
# ==================================================

last_record = frappe.get_all(
    "Employee Checkin",
    filters={
        "employee": doc.employee,
        "time": ["between", [cycle_start, attendance_time]]
    },
    fields=[
        "name",
        "time",
        "log_type",
        "custom_source"
    ],
    order_by="time asc, creation asc"
)

filtered_records = []

for row in last_record:

    if row.name == doc.name:
        continue

    filtered_records.append(row)

# ==================================================
# WEB VALIDATION ONLY
# ==================================================

if doc.custom_source != "Biometric":

    if len(filtered_records) == 0:

        if doc.log_type == "OUT":

            frappe.throw(
                "Please check in first."
            )

    else:

        current_punch = len(filtered_records) + 1

        if current_punch % 2 == 1:

            if doc.log_type != "IN":

                frappe.throw(
                    "You have already checked out. Please check in first."
                )

        else:

            if doc.log_type != "OUT":

                frappe.throw(
                    "You have already checked in. Please check out first."
                )
